import{az as a,P as n,Q as l,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"css/新特性/nesting.md","filePath":"css/新特性/nesting.md","lastUpdated":1785249401000}'),p={name:"css/新特性/nesting.md"};function e(t,s,c,r,F,D){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h2 id="css-原生嵌套-css-nesting" tabindex="-1">CSS 原生嵌套（CSS Nesting） <a class="header-anchor" href="#css-原生嵌套-css-nesting" aria-label="Permalink to “CSS 原生嵌套（CSS Nesting）”">​</a></h2><blockquote><p>MDN 参考：<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_nesting" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_nesting</a></p></blockquote><p>CSS 原生嵌套允许开发者在选择器内部直接嵌套子选择器，无需依赖 Sass、Less 等预处理器。它让样式表更清晰、更贴近 HTML 结构，同时减少了重复的父选择器书写。</p><h3 id="一、为什么需要原生嵌套" tabindex="-1">一、为什么需要原生嵌套 <a class="header-anchor" href="#一、为什么需要原生嵌套" aria-label="Permalink to “一、为什么需要原生嵌套”">​</a></h3><p>在传统 CSS 中，针对同一组件的不同状态往往要重复书写父选择器：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> padding</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 16px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 18px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;">:</span><span style="color:#C792EA;">hover</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> box-shadow</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#F78C6C;"> 4px</span><span style="color:#F78C6C;"> 12px</span><span style="color:#82AAFF;"> rgba</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">.1</span><span style="color:#89DDFF;">);</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;">:</span><span style="color:#C792EA;">hover</span><span style="color:#89DDFF;"> .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">3b82f6</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span></code></pre></div><p>原生嵌套让这些规则可以聚合在一起，逻辑更紧凑：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  padding</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 16px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">  .title { </span><span style="color:#B2CCD6;">font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 18px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">  &amp;</span><span style="color:#89DDFF;">:</span><span style="color:#C792EA;">hover</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">    box-shadow</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#F78C6C;"> 4px</span><span style="color:#F78C6C;"> 12px</span><span style="color:#82AAFF;"> rgba</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;">.1</span><span style="color:#89DDFF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    .title { </span><span style="color:#B2CCD6;">color</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">3b82f6</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">  }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><h3 id="二、嵌套语法与-符号" tabindex="-1">二、嵌套语法与 &amp; 符号 <a class="header-anchor" href="#二、嵌套语法与-符号" aria-label="Permalink to “二、嵌套语法与 &amp; 符号”">​</a></h3><p><code>&amp;</code> 代表父选择器，用于显式引用外层选择器。它的位置决定了最终生成的选择器：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">button</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 直接嵌套，等价于 .button .icon */</span></span>
<span class="line"><span style="color:#BABED8;">  .</span><span style="color:#B2CCD6;">icon</span><span style="color:#BABED8;"> { </span><span style="color:#B2CCD6;">width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 16px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 使用 &amp;，等价于 .button:hover */</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;</span><span style="color:#89DDFF;">:</span><span style="color:#C792EA;">hover</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> background</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">ef4444</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* &amp; 在后面，等价于父级 .button .wrapper */</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">wrapper</span><span style="color:#BABED8;"> &amp; </span><span style="color:#89DDFF;">{</span><span style="color:#B2CCD6;"> margin</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><p><code>&amp;</code> 也可拼接使用，常用于 BEM 命名约定：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;__title { </span><span style="color:#B2CCD6;">font-weight</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> bold</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;__body </span><span style="color:#89DDFF;">{</span><span style="color:#B2CCD6;"> padding</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 12px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;--active </span><span style="color:#89DDFF;">{</span><span style="color:#B2CCD6;"> border-color</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">3b82f6</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* 生成 .card__title / .card__body / .card--active */</span></span></code></pre></div><h3 id="三、嵌套选择器规则" tabindex="-1">三、嵌套选择器规则 <a class="header-anchor" href="#三、嵌套选择器规则" aria-label="Permalink to “三、嵌套选择器规则”">​</a></h3><p>原生嵌套对选择器类型有要求：</p><ul><li><strong>以符号开头的复合选择器必须用 <code>&amp;</code></strong>：例如 <code>:hover</code>、<code>.mod</code>、<code>[disabled]</code>，必须写成 <code>&amp;:hover</code>、<code>&amp;.mod</code>、<code>&amp;[disabled]</code>。</li><li><strong>以类型选择器或通用选择器开头时可不加 <code>&amp;</code></strong>：例如 <code>.card h2</code> 可直接写 <code>h2 { ... }</code>。</li><li>任意选择器都可用 <code>&amp;</code> 显式引用，推荐始终使用以提高可读性。</li></ul><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">form</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#BABED8;">  input { </span><span style="color:#676E95;font-style:italic;">/* 合法，类型选择器 */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">invalid</span><span style="color:#89DDFF;"> {</span><span style="color:#676E95;font-style:italic;"> /* 合法，类选择器加 &amp; */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">  :</span><span style="color:#C792EA;">focus</span><span style="color:#89DDFF;"> {</span><span style="color:#676E95;font-style:italic;"> /* ❌ 非法，伪类必须用 &amp; */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">  &amp;</span><span style="color:#89DDFF;">:</span><span style="color:#C792EA;">focus</span><span style="color:#89DDFF;"> {</span><span style="color:#676E95;font-style:italic;"> /* ✅ 合法 */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><h3 id="四、与-sass-less-的异同" tabindex="-1">四、与 Sass / Less 的异同 <a class="header-anchor" href="#四、与-sass-less-的异同" aria-label="Permalink to “四、与 Sass / Less 的异同”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>原生 CSS 嵌套</th><th>Sass 嵌套</th></tr></thead><tbody><tr><td>运行方式</td><td>浏览器原生解析</td><td>需编译为标准 CSS</td></tr><tr><td><code>&amp;</code> 用法</td><td>支持，代表父选择器</td><td>支持，行为基本一致</td></tr><tr><td>嵌套 <code>@media</code></td><td>支持</td><td>支持</td></tr><tr><td>性能</td><td>原生，无构建开销</td><td>需构建步骤</td></tr><tr><td>深层嵌套风险</td><td>同样存在选择器爆炸问题</td><td>同样存在</td></tr></tbody></table><p>主要区别在于：原生嵌套对 <code>&amp;</code> 的使用更严格（以符号开头的复合选择器必须显式用 <code>&amp;</code>），而 Sass 在很多情况下可以省略。</p><h3 id="五、嵌套媒体查询与容器查询" tabindex="-1">五、嵌套媒体查询与容器查询 <a class="header-anchor" href="#五、嵌套媒体查询与容器查询" aria-label="Permalink to “五、嵌套媒体查询与容器查询”">​</a></h3><p>嵌套不只针对选择器，<code>@media</code>、<code>@container</code>、<code>@supports</code> 等都可以嵌套：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">sidebar</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 240px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">  @media (</span><span style="color:#B2CCD6;">max-width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 768px</span><span style="color:#BABED8;">) {</span></span>
<span class="line"><span style="color:#B2CCD6;">    width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 100%</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  @container</span><span style="color:#BABED8;"> (min-width: 400px) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#BABED8;">    padding: 24px;</span></span>
<span class="line"><span style="color:#BABED8;">  }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><h3 id="六、使用建议" tabindex="-1">六、使用建议 <a class="header-anchor" href="#六、使用建议" aria-label="Permalink to “六、使用建议”">​</a></h3><ol><li><strong>避免过度嵌套</strong>：嵌套超过 3 层会导致选择器性能下降且难以维护。</li><li><strong>优先使用 <code>&amp;</code></strong>：显式引用父选择器，避免歧义。</li><li><strong>与 BEM 配合</strong>：<code>&amp;__element</code> 写法天然契合 BEM 规范。</li><li><strong>迁移注意</strong>：从 Sass 迁移时，检查 <code>&amp;</code> 的使用是否符合原生规范。</li></ol><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">/* ❌ 过度嵌套，不推荐 */</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">nav</span><span style="color:#FFCB6B;"> ul</span><span style="color:#FFCB6B;"> li</span><span style="color:#FFCB6B;"> a</span><span style="color:#FFCB6B;"> span</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* ✅ 扁平化更清晰 */</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">nav-link-text</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span></code></pre></div><h3 id="七、浏览器兼容性" tabindex="-1">七、浏览器兼容性 <a class="header-anchor" href="#七、浏览器兼容性" aria-label="Permalink to “七、浏览器兼容性”">​</a></h3><p>CSS 原生嵌套已全面普及：</p><ul><li>Chrome / Edge：112+（2023 年 4 月，初版）/ 120+（完整支持）</li><li>Safari：16.5+（2023 年 5 月）</li><li>Firefox：117+（2023 年 8 月）</li></ul><p>早期实现（Chrome 112-119）对未加 <code>&amp;</code> 的复合选择器存在解析限制，2023 年底后的版本已完整支持。为保证旧版本兼容，建议始终显式使用 <code>&amp;</code>。也可借助 PostCSS <code>postcss-nesting</code> 自动降级转换。</p>`,30)])])}const C=a(p,[["render",e]]);export{d as __pageData,C as default};
